 const route=(verb,p,fn)=>app[verb]('/api/training'+p,auth,asyncRoute(fn));const id=v=>{let n=Number(v);if(!Number.isSafeInteger(n)||n<1)S.fail('Identifiant invalide.');return n};
 const text=(v,name,max=4000,optional=false)=>{if(optional&&(v==null||v===''))return '';if(typeof v!=='string'||!v.trim()||v.trim().length>max||/[\u0000-\u001f]/.test(v))S.fail(name+' invalide.');return v.trim()},date=(v,name)=>{let d=new Date(v);if(!v||!Number.isFinite(d.getTime()))S.fail(name+' invalide.');return d.toISOString()},choice=(v,choices,name)=>{if(!choices.includes(v))S.fail(name+' invalide.');return v};
 const leaders=new Set(['platform_admin','regional_director','school_head']);const formats=['onsite','distance','hybrid','workshop','conference','webinar','seminar','self_paced'];const scopes=a=>a.role_key==='platform_admin'?{scope:'platform',region_id:null,organization_id:null}:a.role_key==='regional_director'?{scope:'region',region_id:a.region_id,organization_id:null}:a.role_key==='school_head'?{scope:'school',region_id:a.region_id,organization_id:a.organization_id}:null;
