 route('get','/courses/:id',async(req,res)=>{let r=await course(pool,id(req.params.id),req.actor),manager=authority(r,req.actor),coach=trainer(r,req.actor),staffViewer=req.actor.role_key==='school_head'&&(r.scope==='platform'||r.scope==='region'&&String(r.region_id)===String(req.actor.region_id))&&!manager&&!coach,[sessions,resources,assessments,own,participants]=await Promise.all([pool.query('SELECT id,title,starts_at,ends_at,location FROM training_sessions WHERE course_id=$1 ORDER BY starts_at,id',[r.id]),pool.query('SELECT id,file_name,mime_type,file_size,created_at FROM training_resources WHERE course_id=$1 ORDER BY id',[r.id]),pool.query('SELECT id,phase,title,published_at FROM training_assessments WHERE course_id=$1 ORDER BY id',[r.id]),pool.query('SELECT id,status FROM training_enrollments WHERE course_id=$1 AND account_id=$2',[r.id,req.actor.id]),manager||coach||staffViewer?pool.query('SELECT e.id,e.account_id,a.full_name,a.role_key,a.organization_id,e.status FROM training_enrollments e JOIN accounts a ON a.id=e.account_id WHERE e.course_id=$1 AND ($2::bigint IS NULL OR a.organization_id=$2) ORDER BY e.id LIMIT 500',[r.id,staffViewer?req.actor.organization_id:null]):Promise.resolve({rows:[]})]);await tx(pool,c=>audit(c,req,'training.view','training_course',r.id,r.region_id));let {revoked_at,role_key_at_grant,organization_id_at_grant,grant_id,...publicCourse}=r;res.json({course:publicCourse,sessions:sessions.rows,resources:resources.rows,assessments:assessments.rows,enrollment:own.rows[0]||null,participants:participants.rows,can_manage:coach,can_approve:manager,staff_view:staffViewer})});
 route('post','/courses/:id/sessions',async(req,res)=>{let n=id(req.params.id),title=text(req.body?.title,'Séance',160),start=date(req.body?.starts_at,'Début'),end=date(req.body?.ends_at,'Fin'),location=text(req.body?.location,'Lieu ou accès',300,true);if(end<=start)S.fail('Fin avant début.');let x=await tx(pool,async c=>{let r=await course(c,n,req.actor,'manage',true);if(r.status==='archived'||(await c.query('SELECT 1 FROM training_certificate_requests p JOIN training_enrollments e ON e.id=p.enrollment_id WHERE e.course_id=$1 LIMIT 1',[n])).rowCount)S.fail('Séances figées après proposition d’attestation ou archivage.',409);let out=(await c.query('INSERT INTO training_sessions(course_id,title,starts_at,ends_at,location,created_by) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id',[n,title,start,end,location,req.actor.id])).rows[0];await event(c,req,r,'session',null,{session_id:out.id});return out});res.status(201).json(x)});
 route('post','/courses/:id/publish',async(req,res)=>{let n=id(req.params.id),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'approve',true);if(r.status!=='draft')S.fail('Déjà publiée ou archivée.',409);if(!(await c.query('SELECT 1 FROM training_sessions WHERE course_id=$1 LIMIT 1',[n])).rowCount)S.fail('Programmez au moins une séance.',409);let x=(await c.query("UPDATE training_courses SET status='published',approved_by=$1,published_at=now(),updated_at=now() WHERE id=$2 RETURNING id,status",[req.actor.id,n])).rows[0];await event(c,req,r,'publish');return x});res.json(out)});
 route('post','/courses/:id/archive',async(req,res)=>{let n=id(req.params.id),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'approve',true);if(r.status!=='published')S.fail('Formation non publiée.',409);let x=(await c.query("UPDATE training_courses SET status='archived',updated_at=now() WHERE id=$1 RETURNING id,status",[n])).rows[0];await event(c,req,r,'archive');return x});res.json(out)});
 async function available(c,r,p){if(!belongs(r,p)||!r.target_roles.includes(p.role_key))S.fail('Public cible ou périmètre non autorisé.',403)}
 async function checkAvailability(c,r,personId){if(r.format==='self_paced')return;let conflict=await c.query("SELECT 1 FROM training_sessions target JOIN training_sessions current_s ON current_s.starts_at<target.ends_at AND target.starts_at<current_s.ends_at JOIN training_enrollments old_e ON old_e.course_id=current_s.course_id JOIN training_courses old_c ON old_c.id=old_e.course_id WHERE target.course_id=$1 AND current_s.course_id<>$1 AND old_e.account_id=$2 AND old_e.status IN ('confirmed','completed') AND old_c.format<>'self_paced' AND current_s.ends_at>now() LIMIT 1",[r.id,personId]);if(conflict.rowCount)S.fail('Séance incompatible avec une formation déjà confirmée.',409)}
 async function seat(c,r){let x=(await c.query("SELECT count(*)::int n FROM training_enrollments WHERE course_id=$1 AND status IN ('confirmed','completed')",[r.id])).rows[0].n;return x<r.capacity}
 route('post','/courses/:id/invite',async(req,res)=>{let n=id(req.params.id),uid=id(req.body?.account_id),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'read',true);if(!trainer(r,req.actor)&&!authority(r,req.actor)||r.status!=='published')S.fail('Convocation non autorisée.',403);let p=await account(c,uid);await available(c,r,p);let existing=await c.query('SELECT id,status FROM training_enrollments WHERE course_id=$1 AND account_id=$2 FOR UPDATE',[n,uid]);if(existing.rowCount&&['invited','confirmed','completed'].includes(existing.rows[0].status))S.fail('Déjà invité ou inscrit.',409);let e=(existing.rowCount?await c.query("UPDATE training_enrollments SET status='invited',invited_by=$1,updated_at=now() WHERE id=$2 RETURNING id",[req.actor.id,existing.rows[0].id]):await c.query("INSERT INTO training_enrollments(course_id,account_id,status,invited_by) VALUES ($1,$2,'invited',$3) RETURNING id",[n,uid,req.actor.id])).rows[0];await event(c,req,r,'invite',e.id,{account_id:uid});await notify(c,uid,'new','training',n,'training:invite:'+e.id+':'+Date.now(),'Convocation à une formation',e.id);return e});res.status(201).json(out)});
 route('post','/courses/:id/enroll',async(req,res)=>{let n=id(req.params.id),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'read',true);if(r.status!=='published')S.fail('Inscriptions fermées.',409);await available(c,r,req.actor);if(r.enrollment_open_at&&new Date(r.enrollment_open_at)>new Date()||r.enrollment_close_at&&new Date(r.enrollment_close_at)<new Date())S.fail('Inscriptions fermées pour cette période.',409);let old=await c.query('SELECT id,status FROM training_enrollments WHERE course_id=$1 AND account_id=$2 FOR UPDATE',[n,req.actor.id]);if(old.rowCount&&['confirmed','completed'].includes(old.rows[0].status))S.fail('Déjà inscrit.',409);await checkAvailability(c,r,req.actor.id);let status=await seat(c,r)?'confirmed':'waitlisted',e=(old.rowCount?await c.query('UPDATE training_enrollments SET status=$1,updated_at=now() WHERE id=$2 RETURNING id',[status,old.rows[0].id]):await c.query('INSERT INTO training_enrollments(course_id,account_id,status) VALUES ($1,$2,$3) RETURNING id',[n,req.actor.id,status])).rows[0];await event(c,req,r,'enroll',e.id,{status});return {id:e.id,status}});res.status(201).json(out)});
 route('post','/enrollments/:id/respond',async(req,res)=>{let n=id(req.params.id),decision=choice(req.body?.decision,['confirm','decline','unavailable','cancel'],'Décision'),out=await tx(pool,async c=>{let e=await enrollment(c,n,req.actor,'self',true),r=await course(c,Number(e.course_id),req.actor,'read',true);if(r.status!=='published')S.fail('Formation archivée.',409);let next;if(e.status==='invited'&&decision==='confirm'){await checkAvailability(c,r,req.actor.id);next=await seat(c,r)?'confirmed':'waitlisted'}else if(e.status==='invited'&&['decline','unavailable'].includes(decision))next=decision==='decline'?'declined':'declined';else if(['confirmed','waitlisted'].includes(e.status)&&decision==='cancel'){if((await c.query('SELECT 1 FROM training_attempts WHERE enrollment_id=$1 LIMIT 1',[n])).rowCount||(await c.query('SELECT 1 FROM training_certificate_requests WHERE enrollment_id=$1 LIMIT 1',[n])).rowCount)S.fail('Une évaluation ou une proposition d’attestation empêche cette annulation.',409);next='cancelled'}else S.fail('Décision impossible à ce stade.',409);await c.query('UPDATE training_enrollments SET status=$1,updated_at=now() WHERE id=$2',[next,n]);await event(c,req,r,'respond',n,{decision,status:next});return {status:next}});res.json(out)});
