 route('post','/courses/:id/assessments',async(req,res)=>{let n=id(req.params.id),phase=choice(req.body?.phase,['pre','post'],'Phase'),title=text(req.body?.title,'Évaluation',160),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'manage',true);if(r.status==='archived')S.fail('Formation archivée.',409);let x=(await c.query('INSERT INTO training_assessments(course_id,phase,title,created_by) VALUES ($1,$2,$3,$4) RETURNING id',[n,phase,title,req.actor.id])).rows[0];await event(c,req,r,'assessment.create',null,{assessment_id:x.id,phase});return x});res.status(201).json(out)});
 async function assessment(c,n,a,manage=false,lock=false){let x=await c.query(`SELECT ass.*,t.trainer_id,t.scope,t.region_id,t.organization_id,t.target_roles,t.status course_status,g.id grant_id,g.revoked_at,g.role_key_at_grant,g.organization_id_at_grant FROM training_assessments ass JOIN training_courses t ON t.id=ass.course_id LEFT JOIN training_trainer_grants g ON g.id=t.trainer_grant_id WHERE ass.id=$1 ${lock?'FOR UPDATE OF ass':''}`,[n]);if(!x.rowCount)S.fail('Évaluation introuvable.',404);let r=x.rows[0];if(manage?!trainer(r,a):!r.published_at||!belongs(r,a)||!r.target_roles.includes(a.role_key))S.fail('Évaluation inaccessible.',404);return r}
 route('post','/assessments/:id/questions',async(req,res)=>{let n=id(req.params.id),kind=choice(req.body?.kind,['mcq','short','practical'],'Type'),prompt=text(req.body?.prompt,'Question',1000),points=Number(req.body?.points),answer=kind==='practical'?null:text(req.body?.answer,'Réponse',300),choices=kind==='mcq'?req.body?.choices:null;if(!Number.isInteger(points)||points<1||points>100||kind==='mcq'&&(!Array.isArray(choices)||choices.length<2||choices.length>8||choices.some(v=>typeof v!=='string'||v.length>160||!v.trim())||new Set(choices).size!==choices.length||!choices.includes(answer)))S.fail('Barème ou choix invalide.');let out=await tx(pool,async c=>{let a=await assessment(c,n,req.actor,true,true);if(a.published_at||a.course_status==='archived')S.fail('Questions figées après publication ou archivage.',409);if((await c.query('SELECT count(*)::int n FROM training_questions WHERE assessment_id=$1',[n])).rows[0].n>=40)S.fail('Limite de 40 questions.',409);let x=(await c.query('INSERT INTO training_questions(assessment_id,kind,prompt,choices,answer,points) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id',[n,kind,prompt,choices?JSON.stringify(choices):null,answer,points])).rows[0];await event(c,req,{id:a.course_id,region_id:a.region_id},'question.create',null,{question_id:x.id});return x});res.status(201).json(out)});
