 const normalize=x=>x.normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('fr');
 route('post','/assessments/:id/attempts',async(req,res)=>{let n=id(req.params.id),responses=req.body?.responses;if(!responses||typeof responses!=='object'||Array.isArray(responses))S.fail('Réponses invalides.');let out=await tx(pool,async c=>{let a=await assessment(c,n,req.actor,false,true),e=(await c.query("SELECT id FROM training_enrollments WHERE course_id=$1 AND account_id=$2 AND status='confirmed' FOR UPDATE",[a.course_id,req.actor.id])).rows[0];if(!e)S.fail('Inscription confirmée nécessaire.',403);let qs=(await c.query('SELECT id,kind,choices,answer,points FROM training_questions WHERE assessment_id=$1 ORDER BY id',[n])).rows,answers={},auto=0,total=0,practical=0;for(let q of qs){let value=responses[String(q.id)];if(typeof value!=='string'||value.length>2000||!value.trim())S.fail('Répondez à chaque question.');if(q.kind==='mcq'&&!q.choices.includes(value))S.fail('Choix invalide.');answers[q.id]=value.trim();total+=q.points;if(q.kind==='practical')practical++;else if(q.kind==='mcq'?value===q.answer:normalize(value)===normalize(q.answer))auto+=q.points}if(Object.keys(responses).length!==qs.length||!qs.length)S.fail('Nombre de réponses invalide.');let score=practical?null:Math.round(auto/total*10000)/100,x=(await c.query('INSERT INTO training_attempts(assessment_id,enrollment_id,responses,auto_points,total_points,score_percent,finalized_at) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id,score_percent,finalized_at',[n,e.id,JSON.stringify(answers),auto,total,score,practical?null:new Date().toISOString()])).rows[0];await event(c,req,{id:a.course_id,region_id:a.region_id},'attempt',e.id,{assessment_id:n,attempt_id:x.id,auto_points:auto,practical_pending:practical});return x});res.status(201).json(out)});
 route('get','/assessments/:id/submissions',async(req,res)=>{let n=id(req.params.id),a=await assessment(pool,n,req.actor,true),x=await pool.query('SELECT at.id,at.enrollment_id,p.full_name,at.responses,at.auto_points,at.manual_points,at.total_points,at.score_percent,at.finalized_at,at.submitted_at FROM training_attempts at JOIN training_enrollments e ON e.id=at.enrollment_id JOIN accounts p ON p.id=e.account_id WHERE at.assessment_id=$1 ORDER BY at.id LIMIT 200',[n]),qs=await pool.query('SELECT id,kind,prompt,choices,answer,points FROM training_questions WHERE assessment_id=$1 ORDER BY id',[n]);res.json({items:x.rows,questions:qs.rows})});
 route('post','/attempts/:id/grades',async(req,res)=>{let n=id(req.params.id),questionId=id(req.body?.question_id),points=Number(req.body?.points),feedback=text(req.body?.feedback,'Appréciation',800,true);let out=await tx(pool,async c=>{let at=(await c.query('SELECT * FROM training_attempts WHERE id=$1 FOR UPDATE',[n])).rows[0];if(!at||at.finalized_at)S.fail('Évaluation déjà finalisée ou introuvable.',409);let a=await assessment(c,Number(at.assessment_id),req.actor,true),q=(await c.query("SELECT id,points FROM training_questions WHERE id=$1 AND assessment_id=$2 AND kind='practical'",[questionId,a.id])).rows[0];if(!q||!Number.isInteger(points)||points<0||points>q.points)S.fail('Barème pratique invalide.');let added=await c.query('INSERT INTO training_manual_grades(attempt_id,question_id,points,feedback,graded_by) VALUES ($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING RETURNING question_id',[n,questionId,points,feedback,req.actor.id]);if(!added.rowCount)S.fail('Question déjà corrigée.',409);let result=await c.query("SELECT count(*)::int total,(SELECT count(*)::int FROM training_manual_grades g WHERE g.attempt_id=$1) graded,coalesce((SELECT sum(points)::int FROM training_manual_grades g WHERE g.attempt_id=$1),0) points FROM training_questions WHERE assessment_id=$2 AND kind='practical'",[n,a.id]),v=result.rows[0],final=v.total===v.graded,score=final?Math.round((at.auto_points+v.points)/at.total_points*10000)/100:null;await c.query('UPDATE training_attempts SET manual_points=$1,score_percent=$2,finalized_at=$3 WHERE id=$4',[v.points,score,final?new Date().toISOString():null,n]);await event(c,req,{id:a.course_id,region_id:a.region_id},'grade',at.enrollment_id,{question_id:questionId,attempt_id:n,final});return {finalized:final,score_percent:score}});res.json(out)});
