 route('get','/certificates/pending',async(req,res)=>{let a=req.actor;if(!leaders.has(a.role_key))S.fail('Réservé aux autorités.',403);let x=await pool.query(`SELECT p.enrollment_id,e.account_id,u.full_name,t.id course_id,t.title,t.scope,t.region_id,t.organization_id,p.proposed_at FROM training_certificate_requests p JOIN training_enrollments e ON e.id=p.enrollment_id JOIN training_courses t ON t.id=e.course_id JOIN accounts u ON u.id=e.account_id WHERE p.status='pending' ORDER BY p.proposed_at LIMIT 100`);res.json({items:x.rows.filter(r=>authority(r,a))})});
 route('post','/certificates/:enrollmentId/review',async(req,res)=>{let n=id(req.params.enrollmentId),decision=choice(req.body?.decision,['approved','rejected'],'Décision'),note=req.body?.note?text(req.body.note,'Motif',1000):null;if(decision==='rejected'&&!note)S.fail('Motif du rejet requis.');let out=await tx(pool,async c=>{let x=await c.query('SELECT p.*,e.course_id,e.account_id,e.status enrollment_status FROM training_certificate_requests p JOIN training_enrollments e ON e.id=p.enrollment_id WHERE p.enrollment_id=$1 FOR UPDATE OF p,e',[n]),request=x.rows[0];if(!request||request.status!=='pending')S.fail('Proposition introuvable ou déjà décidée.',404);let r=await course(c,Number(request.course_id),req.actor,'approve',true),e=await enrollment(c,n,req.actor,'authority',false),check=await eligibility(c,e);if(decision==='approved'&&!check.eligible)S.fail('Conditions de participation non remplies.',409);await c.query('UPDATE training_certificate_requests SET status=$1,reviewed_by=$2,reviewed_at=now(),review_note=$3 WHERE enrollment_id=$4',[decision,req.actor.id,note,n]);let reference=null;if(decision==='approved'){reference='DRENAET-FC-'+crypto.randomBytes(16).toString('hex').toUpperCase();let user=await account(c,Number(e.account_id));await c.query('INSERT INTO training_certificates(enrollment_id,reference,participant_name,course_title,provider,duration_minutes,validated_by,validator_name) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)',[n,reference,user.full_name,r.title,r.provider,r.duration_minutes,req.actor.id,req.actor.full_name]);await c.query("UPDATE training_enrollments SET status='completed',updated_at=now() WHERE id=$1",[n]);await notify(c,e.account_id,'new','training',r.id,'training:certificate:'+n,'Attestation de formation disponible',n)}await event(c,req,r,'certificate.review',n,{decision,reference});return {decision,reference}});res.json(out)});
 async function certificatePdf(x){let doc=new PDFDocument({size:'A4',margin:55,info:{Title:'Attestation de formation '+x.reference,Author:'DRENAET CI'}}),chunks=[];doc.on('data',b=>chunks.push(b));let done=new Promise((resolve,reject)=>{doc.on('end',()=>resolve(Buffer.concat(chunks)));doc.on('error',reject)});doc.font('Helvetica-Bold').fontSize(19).text('DRENAET CI — Attestation de participation',{align:'center'});doc.moveDown(2).font('Helvetica').fontSize(12).text('La participation de '+x.participant_name+' à la formation « '+x.course_title+' » a été validée.');doc.moveDown().text('Durée : '+x.duration_minutes+' minutes').text('Organisme ou autorité responsable : '+x.provider).text('Date de validation : '+new Date(x.issued_at).toISOString().slice(0,10)).text('Référence unique : '+x.reference).text('Autorité ayant validé : '+x.validator_name);doc.moveDown(2).fontSize(10).text('Référence vérifiable dans DRENAET CI. Document validé administrativement ; aucune signature électronique qualifiée n’est revendiquée.');doc.end();return done}
 route('get','/certificates/:reference/pdf',async(req,res)=>{let ref=String(req.params.reference||'');if(!/^DRENAET-FC-[0-9A-F]{32}$/.test(ref))S.fail('Référence invalide.',404);let x=(await pool.query('SELECT c.*,e.account_id,t.scope,t.region_id,t.organization_id FROM training_certificates c JOIN training_enrollments e ON e.id=c.enrollment_id JOIN training_courses t ON t.id=e.course_id WHERE c.reference=$1',[ref])).rows[0];if(!x||String(x.account_id)!==String(req.actor.id)&&!authority(x,req.actor))S.fail('Attestation inaccessible.',404);let bytes=await certificatePdf(x);await tx(pool,c=>audit(c,req,'training.certificate.download','training_certificate',x.id,x.region_id));res.set({'Content-Type':'application/pdf','Content-Disposition':`attachment; filename="attestation-${ref}.pdf"`,'Cache-Control':'private, no-store'});res.send(bytes)});
 // La référence aléatoire (128 bits) est le seul moyen de consultation publique, sans liste ni données d'accès.
