 route('post','/resources/:courseId',async(req,res)=>{let n=id(req.params.courseId),file=String(req.get('x-resource-name')||''),mime=String(req.get('x-resource-mime')||'').toLowerCase(),raw=req.body;try{file=decodeURIComponent(file)}catch{S.fail('Nom invalide.')}if(!file||file.length>120||/[\\/<>:"|?*\u0000-\u001f]/.test(file)||!types[mime]||!types[mime][0].test(file)||!Buffer.isBuffer(raw)||!raw.length||raw.length>10485760||!types[mime][1](raw))S.fail('Support invalide ou supérieur à 10 Mio.');let hash=crypto.createHash('sha256').update(raw).digest('hex'),out=await tx(pool,async c=>{let r=await course(c,n,req.actor,'manage',true);if(r.status==='archived')S.fail('Formation archivée.',409);let settings=(await c.query('SELECT * FROM training_settings WHERE id=1 FOR UPDATE')).rows[0],used=(await c.query('SELECT count(*)::int n,coalesce(sum(file_size),0)::bigint bytes FROM training_resources')).rows[0];if(raw.length>settings.max_file_mib*1048576)S.fail('Fichier supérieur à la limite définie par l’administration.',413);if(used.n>=settings.max_resources||Number(used.bytes)+raw.length>settings.max_total_mib*1048576)S.fail('Quota des supports atteint.',409);let x=(await c.query('INSERT INTO training_resources(course_id,file_name,mime_type,file_size,file_data,sha256,uploaded_by) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id',[n,file,mime,raw.length,raw,hash,req.actor.id])).rows[0];await event(c,req,r,'resource',null,{resource_id:x.id,bytes:raw.length,sha256:hash});return x});res.status(201).json(out)});
 async function resource(c,n,a){let x=(await c.query('SELECT id,course_id,file_name,mime_type,file_size,file_data FROM training_resources WHERE id=$1',[n])).rows[0];if(!x)S.fail('Support introuvable.',404);await course(c,Number(x.course_id),a);return x}
 route('get','/resources/:id/file',async(req,res)=>{let x=await resource(pool,id(req.params.id),req.actor);await tx(pool,c=>audit(c,req,'training.resource.download','training_resource',x.id,req.actor.region_id));res.set({'Content-Type':x.mime_type,'Content-Disposition':`attachment; filename="support"; filename*=UTF-8''${encodeURIComponent(x.file_name)}`,'Content-Length':String(x.file_size),'Cache-Control':'private, no-store'});res.send(x.file_data)});
