 async function regionalSummary(a){if(!leaders.has(a.role_key))S.fail('Tableau réservé aux responsables.',403);let scope=a.role_key,params=[scope,a.region_id,a.organization_id],where="($1='platform_admin' OR $1='regional_director' AND t.region_id=$2 OR $1='school_head' AND (t.scope='school' AND t.organization_id=$3 OR EXISTS(SELECT 1 FROM training_enrollments z JOIN accounts emp ON emp.id=z.account_id WHERE z.course_id=t.id AND emp.organization_id=$3)))";
 let [courses,participation,distribution,roles,needs]=await Promise.all([
 pool.query(`SELECT count(*)::int organized,count(*) FILTER (WHERE t.status='archived')::int finished FROM training_courses t WHERE ${where}` ,params),
 pool.query(`SELECT count(*)::int registrations,count(*) FILTER (WHERE e.status IN ('confirmed','completed'))::int participating,count(*) FILTER (WHERE e.status='completed')::int completed,count(*) FILTER (WHERE cert.id IS NOT NULL)::int certified FROM training_enrollments e JOIN training_courses t ON t.id=e.course_id JOIN accounts emp ON emp.id=e.account_id LEFT JOIN training_certificates cert ON cert.enrollment_id=e.id WHERE ${where} AND ($1<>'school_head' OR emp.organization_id=$3)`,params),
 pool.query(`SELECT coalesce(o.name,'Sans établissement') school,count(*) FILTER (WHERE e.status IN ('confirmed','completed'))::int participants,count(*) FILTER (WHERE cert.id IS NOT NULL)::int certificates FROM training_enrollments e JOIN training_courses t ON t.id=e.course_id JOIN accounts emp ON emp.id=e.account_id LEFT JOIN organizations o ON o.id=emp.organization_id AND o.kind='school' LEFT JOIN training_certificates cert ON cert.enrollment_id=e.id WHERE ${where} AND ($1<>'school_head' OR emp.organization_id=$3) GROUP BY o.name ORDER BY participants DESC LIMIT 100`,params),
 pool.query(`SELECT emp.role_key,count(*) FILTER (WHERE e.status IN ('confirmed','completed'))::int participants FROM training_enrollments e JOIN training_courses t ON t.id=e.course_id JOIN accounts emp ON emp.id=e.account_id WHERE ${where} AND ($1<>'school_head' OR emp.organization_id=$3) GROUP BY emp.role_key ORDER BY participants DESC`,params),
 pool.query("SELECT count(*)::int n FROM training_needs n JOIN accounts a ON a.id=n.account_id WHERE ($1='platform_admin' OR $1='regional_director' AND a.region_id=$2 OR $1='school_head' AND a.organization_id=$3)",params)]);
 let count=participation.rows[0],rate=count.registrations?Math.round(count.participating/count.registrations*10000)/100:null;return {counts:{...courses.rows[0],...count,needs:needs.rows[0].n,participation_rate:rate},by_school:distribution.rows,by_role:roles.rows,definition:'Taux = inscriptions confirmées ou terminées / toutes inscriptions enregistrées dans le périmètre ; une personne peut avoir plusieurs formations. Formations terminées = archivées, et non attestations automatiquement délivrées.'}}
