 async function remindFor(a,leadHours=24){let due=await pool.query(`SELECT s.id session_id,s.starts_at,e.id enrollment_id,t.id course_id,t.scope,t.region_id,t.organization_id FROM training_sessions s JOIN training_courses t ON t.id=s.course_id JOIN training_enrollments e ON e.course_id=t.id WHERE e.account_id=$1 AND e.status='confirmed' AND t.status='published' AND s.starts_at>=now() AND s.starts_at<=now()+($2::int*interval '1 hour') ORDER BY s.starts_at LIMIT 25`,[a.id,leadHours]);let count=0;for(let v of due.rows){if(!belongs(v,a))continue;let yes=await tx(pool,async c=>{let x=await c.query('INSERT INTO training_reminders(user_id,session_id,starts_at) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING RETURNING user_id',[a.id,v.session_id,v.starts_at]);if(!x.rowCount)return false;await notify(c,a.id,'reminder','training',v.course_id,'training:reminder:'+v.session_id+':'+new Date(v.starts_at).toISOString(),'Séance de formation à venir',v.enrollment_id);return true});if(yes)count++}return count}
 return {remindFor};
